    version_data->features.custom_empire_map_image = version > SAVE_GAME_LAST_NO_CUSTOM_EMPIRE_MAP_IMAGE;
    version_data->features.scenario_version = version > SAVE_GAME_LAST_NO_SCENARIO_VERSION;
